const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Function to mask clouds using the Sentinel-2 QA band.
function maskS2clouds(image) {
  const qa = image.select('QA60');
  // Bits 10 and 11 are clouds and cirrus, respectively.
  const cloudBitMask = 1 << 10;
  const cirrusBitMask = 1 << 11;
  // Both flags should be set to zero, indicating clear conditions.
  const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
  return image.updateMask(mask).divide(10000);
}

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([17.0836, -22.5700]).buffer(5000); // Windhoek, Namibia, 5km buffer
  const date1 = ee.Date('2020-01-29');
  const date2 = ee.Date('2021-02-07');

  // 2. Data Acquisition
  const collection = ee.ImageCollection('COPERNICUS/S2_SR')
                      .filterBounds(aoi);

  const image1_col = collection.filterDate(date1, date1.advance(1, 'day'));
  const image2_col = collection.filterDate(date2, date2.advance(1, 'day'));

  if (image1_col.size().getInfo() === 0 || image2_col.size().getInfo() === 0) {
      console.log(`Image count 2020-01-29: ${image1_col.size().getInfo()}`);
      console.log(`Image count 2021-02-07: ${image2_col.size().getInfo()}`);
      console.log('C1: Empty Collection');
      return;
  }

  // 3. Processing: Create cloud-masked mosaics and calculate NDVI
  const image1 = image1_col.map(maskS2clouds).mosaic();
  const image2 = image2_col.map(maskS2clouds).mosaic();

  const addNDVI = (image) => {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  };

  const ndvi1_img = addNDVI(image1);
  const ndvi2_img = addNDVI(image2);

  const scale = 1000; // Use a coarser scale to avoid timeouts over a large area

  // 4. Calculation & Validation
  const stats1 = ndvi1_img.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const stats2 = ndvi2_img.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  // ee.Dictionary objects need to be evaluated on the server.
  const stats1_info = stats1.getInfo();
  const stats2_info = stats2.getInfo();

  const ndvi1 = stats1_info.NDVI_mean;
  const count1 = stats1_info.NDVI_count;
  const ndvi2 = stats2_info.NDVI_mean;
  const count2 = stats2_info.NDVI_count;

  console.log(`2020-01-29: Mean NDVI = ${ndvi1 ? ndvi1.toFixed(4) : 'N/A'}, Valid Pixels = ${count1 || 0}`);
  console.log(`2021-02-07: Mean NDVI = ${ndvi2 ? ndvi2.toFixed(4) : 'N/A'}, Valid Pixels = ${count2 || 0}`);

  if (count1 === 0 || count2 === 0) {
    console.log('C2: No Valid Pixels');
    return;
  }

  if (ndvi1 === null || ndvi2 === null || isNaN(ndvi1) || isNaN(ndvi2)) {
    console.log('C3: Calculation Failure');
    return;
  }

  // 5. Final Answer
  if (ndvi2 > ndvi1) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Initialization or analysis failed: ${e}`);
    console.log('D');
  }
}

initEE();
